SELECT sum(LO_EXTENDEDPRICE * LO_DISCOUNT) AS revenue FROM lineorder_flat WHERE F_YEAR = 1993 AND LO_DISCOUNT BETWEEN 1 AND 3 AND LO_QUANTITY < 25;
SELECT sum(LO_EXTENDEDPRICE * LO_DISCOUNT) AS revenue FROM lineorder_flat WHERE (EXTRACT(YEAR FROM LO_ORDERDATE)*100 + EXTRACT(MONTH FROM LO_ORDERDATE)) = 199401 AND LO_DISCOUNT BETWEEN 4 AND 6 AND LO_QUANTITY BETWEEN 26 AND 35;
SELECT sum(LO_EXTENDEDPRICE * LO_DISCOUNT) AS revenue FROM lineorder_flat WHERE floor((CAST(LO_ORDERDATE AS DATE) - DATE '1970-01-01') / 7) - floor((CAST(CAST('1994-01-01' AS DATE) AS DATE) - DATE '1970-01-01') / 7) = 6 AND F_YEAR = 1994 AND LO_DISCOUNT BETWEEN 5 AND 7 AND LO_QUANTITY BETWEEN 26 AND 35;
SELECT sum(LO_REVENUE), F_YEAR, P_BRAND FROM lineorder_flat WHERE P_CATEGORY = 'MFGR#12' AND S_REGION = 'AMERICA' GROUP BY F_YEAR, P_BRAND ORDER BY F_YEAR, P_BRAND;
SELECT sum(LO_REVENUE), F_YEAR, P_BRAND FROM lineorder_flat WHERE P_BRAND >= 'MFGR#2221' AND P_BRAND <= 'MFGR#2228' AND S_REGION = 'ASIA' GROUP BY F_YEAR, P_BRAND ORDER BY F_YEAR, P_BRAND;
SELECT sum(LO_REVENUE), F_YEAR, P_BRAND FROM lineorder_flat WHERE P_BRAND = 'MFGR#2239' AND S_REGION = 'EUROPE' GROUP BY F_YEAR, P_BRAND ORDER BY F_YEAR, P_BRAND;
SELECT C_NATION, S_NATION, F_YEAR, sum(LO_REVENUE) AS revenue FROM lineorder_flat WHERE C_REGION = 'ASIA' AND S_REGION = 'ASIA' AND F_YEAR >= 1992 AND F_YEAR <= 1997 GROUP BY C_NATION, S_NATION, F_YEAR ORDER BY F_YEAR ASC, revenue DESC;
SELECT C_CITY, S_CITY, F_YEAR, sum(LO_REVENUE) AS revenue FROM lineorder_flat WHERE C_NATION = 'UNITED STATES' AND S_NATION = 'UNITED STATES' AND F_YEAR >= 1992 AND F_YEAR <= 1997 GROUP BY C_CITY, S_CITY, F_YEAR ORDER BY F_YEAR ASC, revenue DESC;
SELECT C_CITY, S_CITY, F_YEAR, sum(LO_REVENUE) AS revenue FROM lineorder_flat WHERE (C_CITY = 'UNITED KI1' OR C_CITY = 'UNITED KI5') AND (S_CITY = 'UNITED KI1' OR S_CITY = 'UNITED KI5') AND F_YEAR >= 1992 AND F_YEAR <= 1997 GROUP BY C_CITY, S_CITY, F_YEAR ORDER BY F_YEAR ASC, revenue DESC;
SELECT C_CITY, S_CITY, F_YEAR, sum(LO_REVENUE) AS revenue FROM lineorder_flat WHERE (C_CITY = 'UNITED KI1' OR C_CITY = 'UNITED KI5') AND (S_CITY = 'UNITED KI1' OR S_CITY = 'UNITED KI5') AND (EXTRACT(YEAR FROM LO_ORDERDATE)*100 + EXTRACT(MONTH FROM LO_ORDERDATE)) = 199712 GROUP BY C_CITY, S_CITY, F_YEAR ORDER BY F_YEAR ASC, revenue DESC;
SELECT F_YEAR, C_NATION, sum(LO_REVENUE - LO_SUPPLYCOST) AS profit FROM lineorder_flat WHERE C_REGION = 'AMERICA' AND S_REGION = 'AMERICA' AND (P_MFGR = 'MFGR#1' OR P_MFGR = 'MFGR#2') GROUP BY F_YEAR, C_NATION ORDER BY F_YEAR ASC, C_NATION ASC;
SELECT F_YEAR, S_NATION, P_CATEGORY, sum(LO_REVENUE - LO_SUPPLYCOST) AS profit FROM lineorder_flat WHERE C_REGION = 'AMERICA' AND S_REGION = 'AMERICA' AND (F_YEAR = 1997 OR F_YEAR = 1998) AND (P_MFGR = 'MFGR#1' OR P_MFGR = 'MFGR#2') GROUP BY F_YEAR, S_NATION, P_CATEGORY ORDER BY F_YEAR ASC, S_NATION ASC, P_CATEGORY ASC;
SELECT F_YEAR, S_CITY, P_BRAND, sum(LO_REVENUE - LO_SUPPLYCOST) AS profit FROM lineorder_flat WHERE S_NATION = 'UNITED STATES' AND (F_YEAR = 1997 OR F_YEAR = 1998) AND P_CATEGORY = 'MFGR#14' GROUP BY F_YEAR, S_CITY, P_BRAND ORDER BY F_YEAR ASC, S_CITY ASC, P_BRAND ASC;
